To reverse a linked list in JavaScript, you can use a recursive approach. Here's an example code snippet:
function reverseLinkedList(head) {
  if (head === null || head.next === null) {
    return head;
  }
  let next = reverseLinkedList(head.next);
  head.next.next = head;
  head.next = null;
  return next;
}
